using System;
using System.Collections.Generic;
using System.Text;

namespace Shape
{
    public class Circle : Shape
    {
        private const double pi = 3.;
        public double Radius { get; set; }

        public override double Perimeter()
        {
            return 2 * pi * Radius;
        }

        public override double Area()
        {
            return pi * Radius * Radius;
        }
    }
}
